const APP_ICON = "data:image/png;base64,";

export default function FocusGo() {
  useEffect(() => {
    let link = document.querySelector("link[rel~='icon']");
    if (!link) {
      link = document.createElement("link");
      link.rel = "icon";
      document.head.appendChild(link);
    }
    link.href = APP_ICON;
  }, []);

  const [lang, setLang] = useState("en");
  const [dark] = useState(false);
  const [tab, setTab] = useState("today");
  const [now, setNow] = useState(new Date());
  const [entries, setEntries] = useState({}); // dateKey -> [{id, subject, topic, time, endTime, duration, done}]
  const [subjects, setSubjects] = useState([]); // manually managed syllabus subjects
  const [examSubjects, setExamSubjects] = useState({}); // subject -> { topics: { [topicName]: { attempts: [{id, date, obtained, total}] } } }
  const [nextExam, setNextExam] = useState(null); // { subject, topic, date } | null
  const [examMonth, setExamMonth] = useState(new Date());
  const [showExams, setShowExams] = useState(false);
  const [showNextExamEditor, setShowNextExamEditor] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [showAdd, setShowAdd] = useState(false);
  const [addTargetKey, setAddTargetKey] = useState(null);
  const [showSubjects, setShowSubjects] = useState(false);
  const [planDate, setPlanDate] = useState(() => { const d = new Date(); d.setDate(d.getDate() + 1); return d; });
  const [weekExpanded, setWeekExpanded] = useState(false);
  const [showCalendar, setShowCalendar] = useState(false);
  const [calMonth, setCalMonth] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState(null);
  const [timerTopicId, setTimerTopicId] = useState(null);
  const [timerSeconds, setTimerSeconds] = useState(25*60);
  const [timerTotal, setTimerTotal] = useState(25*60);
  const [timerRunning, setTimerRunning] = useState(false);
  const [focusMode, setFocusMode] = useState("timer"); // "timer" | "stopwatch"
  const [stopwatchSeconds, setStopwatchSeconds] = useState(0);
  const [stopwatchRunning, setStopwatchRunning] = useState(false);
  const [focusFullscreen, setFocusFullscreen] = useState(false);
  const [editTopic, setEditTopic] = useState(null);
  const timerRef = useRef(null);
  const stopwatchRef = useRef(null);
  const audioCtxRef = useRef(null);

  // Lightweight beep generator (Web Audio API) — no external sound files needed.
  const getAudioCtx = () => {
    if (!audioCtxRef.current) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return null;
      audioCtxRef.current = new Ctx();
    }
    if (audioCtxRef.current.state === "suspended") {
      audioCtxRef.current.resume().catch(()=>{});
    }
    return audioCtxRef.current;
  };
  const beep = (freq = 880, duration = 0.14, when = 0, volume = 0.45) => {
    try {
      const ctx = getAudioCtx();
      if (!ctx) return;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.value = freq;
      gain.gain.setValueAtTime(0.0001, ctx.currentTime + when);
      gain.gain.exponentialRampToValueAtTime(volume, ctx.currentTime + when + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + when + duration);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(ctx.currentTime + when);
      osc.stop(ctx.currentTime + when + duration + 0.03);
    } catch (e) { /* audio unsupported or blocked — fail silently */ }
  };
  const playStartSound = () => beep(880, 0.12);
  const playEndSound = () => { beep(659, 0.14, 0); beep(880, 0.14, 0.16); beep(1046, 0.22, 0.32); };

  // Toggle helpers used by both the mini timer card and the fullscreen view,
  // so the start sound + auto-fullscreen behavior stays consistent everywhere.
  const toggleTimerRunning = () => {
    setTimerRunning(r => {
      const next = !r;
      if (next) { setFocusFullscreen(true); playStartSound(); }
      return next;
    });
  };
  const toggleStopwatchRunning = () => {
    setStopwatchRunning(r => {
      const next = !r;
      if (next) { setFocusFullscreen(true); playStartSound(); }
      return next;
    });
  };

  const t = T[lang];
  // Bengali conjuncts (যুক্তাক্ষর) visually break apart under CSS letter-spacing,
  // so only apply the wide "eyebrow label" tracking in English.
  const ls = (px) => (lang === "bn" ? 0 : px);
  const today = new Date();
  const todayKey = dateKey(today);

  // load
  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get("dailygo-entries");
        if (res && res.value) setEntries(JSON.parse(res.value));
      } catch (e) { /* no data yet */ }
      try {
        const resS = await window.storage.get("dailygo-subjects");
        if (resS && resS.value) setSubjects(JSON.parse(resS.value));
      } catch (e) { /* no data yet */ }
      try {
        const resE = await window.storage.get("dailygo-exams");
        if (resE && resE.value) {
          const raw = JSON.parse(resE.value);
          // migrate old shape { date, scores:[...] } -> new shape { topics: { General: { attempts:[...] } } }
          let migratedNextExam = null;
          const migrated = {};
          Object.entries(raw).forEach(([subj, info]) => {
            if (info && info.topics) {
              migrated[subj] = info; // already new shape
              return;
            }
            const scores = (info && info.scores) || [];
            const attempts = scores.map(s => ({ id: s.id, date: info?.date || null, obtained: s.obtained, total: s.total }));
            migrated[subj] = { topics: attempts.length ? { General: { attempts } } : {} };
            if (info?.date && scores.length === 0 && !migratedNextExam) {
              migratedNextExam = { subject: subj, topic: "", date: info.date };
            }
          });
          setExamSubjects(migrated);
          if (migratedNextExam) setNextExam(prev => prev || migratedNextExam);
        }
      } catch (e) { /* no data yet */ }
      try {
        const resN = await window.storage.get("dailygo-next-exam");
        if (resN && resN.value) setNextExam(JSON.parse(resN.value));
      } catch (e) { /* no data yet */ }
      try {
        const res2 = await window.storage.get("dailygo-prefs");
        if (res2 && res2.value) {
          const p = JSON.parse(res2.value);
          if (p.lang) setLang(p.lang);
        }
      } catch (e) { /* defaults */ }
      setLoaded(true);
    })();
  }, []);

  // save entries
  useEffect(() => {
    if (!loaded) return;
    window.storage.set("dailygo-entries", JSON.stringify(entries)).catch(()=>{});
  }, [entries, loaded]);

  // save subjects
  useEffect(() => {
    if (!loaded) return;
    window.storage.set("dailygo-subjects", JSON.stringify(subjects)).catch(()=>{});
  }, [subjects, loaded]);

  // save exam subjects
  useEffect(() => {
    if (!loaded) return;
    window.storage.set("dailygo-exams", JSON.stringify(examSubjects)).catch(()=>{});
  }, [examSubjects, loaded]);

  // save next exam
  useEffect(() => {
    if (!loaded) return;
    window.storage.set("dailygo-next-exam", JSON.stringify(nextExam)).catch(()=>{});
  }, [nextExam, loaded]);

  // save prefs
  useEffect(() => {
    if (!loaded) return;
    window.storage.set("dailygo-prefs", JSON.stringify({ lang })).catch(()=>{});
  }, [lang, loaded]);

  // clock tick
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  // timer tick
  useEffect(() => {
    if (timerRunning) {
      timerRef.current = setInterval(() => {
        setTimerSeconds(s => {
          if (s <= 1) { setTimerRunning(false); playEndSound(); return 0; }
          return s - 1;
        });
      }, 1000);
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
    }
    return () => timerRef.current && clearInterval(timerRef.current);
  }, [timerRunning]);

  // stopwatch tick
  useEffect(() => {
    if (stopwatchRunning) {
      stopwatchRef.current = setInterval(() => setStopwatchSeconds(s => s + 1), 1000);
    } else if (stopwatchRef.current) {
      clearInterval(stopwatchRef.current);
    }
    return () => stopwatchRef.current && clearInterval(stopwatchRef.current);
  }, [stopwatchRunning]);

  // keep screen awake while timer or stopwatch is running
  const wakeLockRef = useRef(null);
  useEffect(() => {
    const isActive = timerRunning || stopwatchRunning;
    let cancelled = false;

    const requestLock = async () => {
      try {
        if (navigator.wakeLock && !wakeLockRef.current) {
          const lock = await navigator.wakeLock.request("screen");
          if (cancelled) { lock.release().catch(()=>{}); return; }
          wakeLockRef.current = lock;
          lock.addEventListener("release", () => { wakeLockRef.current = null; });
        }
      } catch (err) {
        // wake lock unsupported or blocked (e.g. low battery, permissions) — fail silently
      }
    };

    const releaseLock = () => {
      if (wakeLockRef.current) {
        wakeLockRef.current.release().catch(()=>{});
        wakeLockRef.current = null;
      }
    };

    if (isActive) {
      requestLock();
      const onVisibility = () => { if (document.visibilityState === "visible") requestLock(); };
      document.addEventListener("visibilitychange", onVisibility);
      return () => { cancelled = true; document.removeEventListener("visibilitychange", onVisibility); releaseLock(); };
    } else {
      releaseLock();
    }
  }, [timerRunning, stopwatchRunning]);

  const todayTopics = entries[todayKey] || [];
  const derivedSubjects = Array.from(new Set(Object.values(entries).flat().map(e => e.subject)));
  const allSubjects = Array.from(new Set([...subjects, ...derivedSubjects]));
  const timerTopic = todayTopics.find(x => x.id === timerTopicId);

  // ---- plan tab: next 7 days, starting tomorrow ----
  const planDays = Array.from({ length: 7 }, (_, i) => { const d = new Date(today); d.setDate(d.getDate() + i + 1); return d; });
  const planKey = dateKey(planDate);
  const isPlanToday = planKey === todayKey;
  const planTopics = entries[planKey] || [];

  // ---- generalized entry CRUD (works for any date, so Plan tab can reuse) ----
  const addTopicFor = (dk, { subject, topic, time, endTime, duration }) => {
    setEntries(prev => {
      const list = prev[dk] ? [...prev[dk]] : [];
      list.push({ id: `${Date.now()}-${Math.random().toString(36).slice(2,7)}`, subject, topic, duration: duration || 30, done: false, time, endTime });
      return { ...prev, [dk]: list };
    });
  };

  const toggleDoneFor = (dk, id) => {
    setEntries(prev => {
      const list = (prev[dk] || []).map(x => x.id === id ? { ...x, done: !x.done } : x);
      return { ...prev, [dk]: list };
    });
  };

  const saveEditFor = (dk, { id, subject, topic, time, endTime, duration }) => {
    setEntries(prev => {
      const list = (prev[dk] || []).map(x => x.id === id ? { ...x, subject, topic, time, endTime, duration } : x);
      return { ...prev, [dk]: list };
    });
  };

  const deleteTopicFor = (dk, id) => {
    setEntries(prev => {
      const list = (prev[dk] || []).filter(x => x.id !== id);
      return { ...prev, [dk]: list };
    });
    if (timerTopicId === id) setTimerTopicId(null);
  };

  // ---- today-tab wrappers ----
  const addTopic = (data) => {
    addTopicFor(addTargetKey || todayKey, data);
    setShowAdd(false);
  };
  const saveEditTopic = (data) => {
    saveEditFor((editTopic && editTopic._dk) || todayKey, data);
    setEditTopic(null);
  };

  // ---- syllabus subject management ----
  const addSubject = (name) => setSubjects(prev => prev.includes(name) ? prev : [...prev, name]);
  const removeSubject = (name) => setSubjects(prev => prev.filter(s => s !== name));
  const addExamSubject = (name) => setExamSubjects(prev => prev[name] ? prev : ({ ...prev, [name]: { topics: {} } }));
  const removeExamSubject = (name) => {
    setExamSubjects(prev => { const next = { ...prev }; delete next[name]; return next; });
    setNextExam(prev => (prev && prev.subject === name) ? null : prev);
  };
  const addExamTopic = (subj, topicName) => {
    const name = (topicName || "").trim();
    if (!name) return;
    setExamSubjects(prev => {
      const cur = prev[subj] || { topics: {} };
      if (cur.topics[name]) return prev;
      return { ...prev, [subj]: { ...cur, topics: { ...cur.topics, [name]: { attempts: [] } } } };
    });
  };
  const removeExamTopic = (subj, topicName) => {
    setExamSubjects(prev => {
      const cur = prev[subj];
      if (!cur) return prev;
      const topics = { ...cur.topics };
      delete topics[topicName];
      return { ...prev, [subj]: { ...cur, topics } };
    });
    setNextExam(prev => (prev && prev.subject === subj && prev.topic === topicName) ? null : prev);
  };
  const addExamAttempt = (subj, topicName, date, obtained, total) => {
    setExamSubjects(prev => {
      const cur = prev[subj] || { topics: {} };
      const curTopic = cur.topics[topicName] || { attempts: [] };
      const attempts = [...(curTopic.attempts || []), { id: `${Date.now()}-${Math.random().toString(36).slice(2,7)}`, date: date || null, obtained, total }];
      return { ...prev, [subj]: { ...cur, topics: { ...cur.topics, [topicName]: { attempts } } } };
    });
  };
  const removeExamAttempt = (subj, topicName, attemptId) => {
    setExamSubjects(prev => {
      const cur = prev[subj];
      if (!cur) return prev;
      const curTopic = cur.topics[topicName];
      if (!curTopic) return prev;
      const attempts = (curTopic.attempts || []).filter(a => a.id !== attemptId);
      return { ...prev, [subj]: { ...cur, topics: { ...cur.topics, [topicName]: { attempts } } } };
    });
  };

  const startTimerFor = (id, duration) => {
    setTimerTopicId(id);
    setTimerSeconds((duration||25)*60);
    setTimerTotal((duration||25)*60);
    setTimerRunning(true);
  };

  const adjustTimer = (deltaMin) => {
    if (timerRunning) return;
    setTimerTotal(prev => {
      const next = Math.max(5*60, Math.min(180*60, prev + deltaMin*60));
      setTimerSeconds(next);
      return next;
    });
  };

  // ---- week data ----
  const weekStart = startOfWeek(today);
  const weekDays = Array.from({length:7}, (_,i) => { const d = new Date(weekStart); d.setDate(d.getDate()+i); return d; });

  // ---- subject progress across all entries ----
  const subjectProgress = {};
  Object.values(entries).flat().forEach(e => {
    if (!subjectProgress[e.subject]) subjectProgress[e.subject] = { done: 0, total: 0 };
    subjectProgress[e.subject].total += 1;
    if (e.done) subjectProgress[e.subject].done += 1;
  });

  // ---- weekly / monthly summary ----
  const rangeEntries = (days) => days.flatMap(d => (entries[dateKey(d)] || []).map(e => ({...e, _dk: dateKey(d)})));
  const weekEntries = rangeEntries(weekDays);
  const monthDays = (() => {
    const y = today.getFullYear(), m = today.getMonth();
    const days = [];
    const last = new Date(y, m+1, 0).getDate();
    for (let i=1;i<=last;i++) days.push(new Date(y,m,i));
    return days;
  })();
  const monthEntries = rangeEntries(monthDays.filter(d => d <= today));

  const nf = (n) => lang === "bn" ? toBn(n) : n;
  const monthName = (i) => lang === "bn" ? MONTHS_BN[i] : MONTHS_EN[i];
  const weekdayName = (d) => lang === "bn" ? WEEKDAYS_BN[d.getDay()] : WEEKDAYS_EN[d.getDay()];
  const weekdayShort = (d) => lang === "bn" ? WEEKDAYS_SHORT_BN[d.getDay()] : WEEKDAYS_SHORT_EN[d.getDay()];

  const fmtTime = (h, m, s) => <>{<Num>{nf(pad2(h))}</Num>}:{<Num>{nf(pad2(m))}</Num>}{s !== undefined ? <>:{<Num>{nf(pad2(s))}</Num>}</> : null}</>;

  // theme tokens
  const bg = dark ? "#1C1A17" : "#F3EFE7";
  const cardBg = dark ? "#26231F" : "#FFFFFF";
  const cardBorder = dark ? "#37332C" : "#E9E3D6";
  const textMain = dark ? "#F3EFE7" : "#211D18";
  const textMuted = dark ? "#9C948400" : "#8A8272";
  const textMuted2 = dark ? "#A69E8C" : "#8A8272";
  const accent = "#D97757";

  const styles = {
    page: { minHeight: "100dvh", background: bg, color: textMain, fontFamily: lang === "bn" ? "'Hind Siliguri','Noto Sans Bengali',sans-serif" : "'Inter','Helvetica Neue',sans-serif", transition: "background .3s,color .3s", display:"flex", flexDirection:"column" },
    container: { maxWidth: 480, margin: "0 auto", padding: "18px 16px 24px", width:"100%", boxSizing:"border-box", flex:"1 0 auto" },
  };

  if (!loaded) {
    return <div style={{...styles.page, display:"flex",alignItems:"center",justifyContent:"center"}}>
      <div style={{opacity:0.5, fontSize:14}}>Loading…</div>
    </div>;
  }

  return (
    <div style={styles.page}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;500;600;700;800&display=swap');
        @import url('https://fonts.maateen.me/kalpurush/font.css');
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&display=swap');
      `}</style>
      <div style={styles.container}>
        {/* Header row: logo | clock | toggles */}
        <div style={{display:"flex", alignItems:"center", justifyContent:"space-between", gap: 8}}>
          <div style={{display:"flex", alignItems:"center", gap:10}}>
            <img src={dark ? LOGO_FULL_DARK : LOGO_FULL} alt="FocusGo" style={{height:26, width:"auto", objectFit:"contain"}}/>
          </div>

          <div style={{display:"flex", alignItems:"center", gap:6}}>
            <GoogleAuthButton cardBorder={cardBorder} textMain={textMain} textMuted2={textMuted2} signInLabel={t.signIn} syncingLabel={t.syncing}/>
            <button onClick={()=>setLang(l=>l==="bn"?"en":"bn")} style={{border:`1px solid ${cardBorder}`, background:cardBg, color:textMain, borderRadius:10, padding:"7px 9px", fontSize:11, fontWeight:700, cursor:"pointer"}}>
              {lang==="bn" ? "EN" : "বাং"}
            </button>
          </div>
        </div>

        {/* Date row */}
        <div style={{display:"flex", justifyContent:"space-between", alignItems:"flex-end", marginTop:22}}>
          <div>
            <div style={{fontSize:11, letterSpacing:ls(1.5), color:textMuted2, fontWeight:700, marginBottom:4}}>{weekdayName(today).toUpperCase()}</div>
            <div style={{display:"flex", alignItems:"baseline", gap:6}}>
              <span style={{fontSize:44, fontWeight:800, lineHeight:1}}><Num>{nf(today.getDate())}</Num></span>
              <span style={{fontSize:16, fontWeight:500, color:textMuted2}}>{monthName(today.getMonth())}</span>
            </div>
          </div>
          <div style={{display:"flex", flexDirection:"column", alignItems:"center", gap:6}}>
            <div style={{fontSize:12, fontWeight:700, color:textMain, fontVariantNumeric:"tabular-nums", letterSpacing:0.3}}>
              <Num>{nf(pad2(((now.getHours()%12)||12)))}</Num>:<Num>{nf(pad2(now.getMinutes()))}</Num>
            </div>
            <button onClick={()=>{vibrate(); setShowCalendar(true); setCalMonth(new Date());}} style={{
              border:"none",
              background: `linear-gradient(145deg, ${accent}, ${dark ? "#B85C3E" : "#C96A45"})`,
              borderRadius:14,
              width:46, height:46,
              display:"flex", alignItems:"center", justifyContent:"center",
              cursor:"pointer",
              boxShadow: `0 6px 16px ${accent}4D, inset 0 1px 0 rgba(255,255,255,0.25)`,
            }}>
              <CalendarDays size={21} color="#fff" strokeWidth={2.2}/>
            </button>
          </div>
        </div>

        {/* Focus timer - only on Today tab */}
        {tab === "today" && (
        <div style={{marginTop:18, background: dark ? "#2B2823" : "#FBF3EC", border:`1px solid ${dark? "#3D372D":"#F0DCC9"}`, borderRadius:18, padding:"14px 16px 16px", color:textMain}}>
          <div style={{display:"flex", justifyContent:"space-between", alignItems:"center"}}>
            <span style={{fontSize:10, letterSpacing:ls(1.5), fontWeight:700, color:textMuted2}}>{t.focusTimer}</span>
            <div style={{display:"flex", alignItems:"center", gap:6}}>
              <div style={{display:"flex", background: dark?"#1C1A17":"#fff", borderRadius:10, padding:3, gap:2}}>
                <button onClick={()=>setFocusMode("timer")} style={{border:"none", borderRadius:8, padding:"4px 9px", fontSize:10, fontWeight:700, cursor:"pointer", background: focusMode==="timer" ? accent : "transparent", color: focusMode==="timer" ? "#fff" : textMuted2}}>{t.timerMode}</button>
                <button onClick={()=>setFocusMode("stopwatch")} style={{border:"none", borderRadius:8, padding:"4px 9px", fontSize:10, fontWeight:700, cursor:"pointer", background: focusMode==="stopwatch" ? accent : "transparent", color: focusMode==="stopwatch" ? "#fff" : textMuted2}}>{t.stopwatchMode}</button>
              </div>
              <button onClick={()=>{vibrate(); setFocusFullscreen(true);}} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2, display:"flex", alignItems:"center", padding:4}}>
                <Maximize2 size={15}/>
              </button>
            </div>
          </div>

          {focusMode === "timer" ? (
            <>
              <div style={{textAlign:"center", margin: timerRunning ? "14px 0 8px" : "8px 0 4px", transition:"margin .25s ease"}}>
                <div style={{fontSize: timerRunning ? 56 : 36, fontWeight:800, fontVariantNumeric:"tabular-nums", letterSpacing:1, color: textMain, transition:"font-size .25s ease"}}>
                  <Num>{nf(pad2(Math.floor(timerSeconds/60)))}:{nf(pad2(timerSeconds%60))}</Num>
                </div>
                <div style={{fontSize:12, color:textMuted2, marginTop:2}}>
                  {timerTopic ? `${timerTopic.subject} · ${timerTopic.topic}` : t.freeSession}
                </div>
                {!timerRunning && (
                  <div style={{display:"flex", justifyContent:"center", alignItems:"center", gap:12, marginTop:8}}>
                    <button onClick={()=>adjustTimer(-5)} style={{width:24,height:24,borderRadius:"50%", border:`1px solid ${dark?"#3D372D":"#F0DCC9"}`, background:"transparent", color:textMain, fontSize:14, fontWeight:700, cursor:"pointer", lineHeight:1}}>−</button>
                    <span style={{fontSize:11, color:textMuted2, fontWeight:700}}><Num>{nf(Math.round(timerTotal/60))}</Num> {t.minutes}</span>
                    <button onClick={()=>adjustTimer(5)} style={{width:24,height:24,borderRadius:"50%", border:`1px solid ${dark?"#3D372D":"#F0DCC9"}`, background:"transparent", color:textMain, fontSize:14, fontWeight:700, cursor:"pointer", lineHeight:1}}>+</button>
                  </div>
                )}
              </div>
              <div style={{display:"flex", gap:8, marginTop:10}}>
                <button
                  onClick={toggleTimerRunning}
                  style={{flex:1, background: accent, border:"none", borderRadius:12, padding:"10px 0", color:"#fff", fontWeight:700, fontSize:13, display:"flex",alignItems:"center",justifyContent:"center", gap:6, cursor:"pointer"}}>
                  {timerRunning ? <Pause size={14} fill="#fff"/> : <Play size={14} fill="#fff"/>} {timerRunning ? t.pause : t.start}
                </button>
                <button onClick={()=>{setTimerRunning(false); setTimerSeconds(timerTotal);}} style={{background: dark?"#3D372D":"#F0DCC9", border:"none", borderRadius:12, width:42, display:"flex",alignItems:"center",justifyContent:"center", cursor:"pointer"}}>
                  <RotateCcw size={15} color={textMain}/>
                </button>
              </div>
            </>
          ) : (
            <>
              <div style={{textAlign:"center", margin: stopwatchRunning ? "14px 0 8px" : "8px 0 4px", transition:"margin .25s ease"}}>
                <div style={{fontSize: stopwatchRunning ? 56 : 36, fontWeight:800, fontVariantNumeric:"tabular-nums", letterSpacing:1, color: textMain, transition:"font-size .25s ease"}}>
                  <Num>{nf(pad2(Math.floor(stopwatchSeconds/60)))}:{nf(pad2(stopwatchSeconds%60))}</Num>
                </div>
                <div style={{fontSize:12, color:textMuted2, marginTop:2}}>
                  {timerTopic ? `${timerTopic.subject} · ${timerTopic.topic}` : t.pickTopicForTimer}
                </div>
              </div>
              <div style={{display:"flex", gap:8, marginTop:10}}>
                <button
                  onClick={toggleStopwatchRunning}
                  style={{flex:1, background: accent, border:"none", borderRadius:12, padding:"10px 0", color:"#fff", fontWeight:700, fontSize:13, display:"flex",alignItems:"center",justifyContent:"center", gap:6, cursor:"pointer"}}>
                  {stopwatchRunning ? <Pause size={14} fill="#fff"/> : <Play size={14} fill="#fff"/>} {stopwatchRunning ? t.pause : t.start}
                </button>
                <button onClick={()=>{setStopwatchRunning(false); setStopwatchSeconds(0);}} style={{background: dark?"#3D372D":"#F0DCC9", border:"none", borderRadius:12, width:42, display:"flex",alignItems:"center",justifyContent:"center", cursor:"pointer"}}>
                  <RotateCcw size={15} color={textMain}/>
                </button>
              </div>
            </>
          )}
        </div>
        )}

        {/* Today's study overview card - Today tab only */}
        {tab === "today" && (
        <div style={{marginTop:14, display:"flex", alignItems:"center", justifyContent:"space-between", background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:16, padding:"14px 16px"}}>
          <div>
            <div style={{fontSize:15, fontWeight:800, marginBottom:8}}>{t.todaysStudy}</div>
            <div style={{display:"flex", alignItems:"center", gap:10, fontSize:13, fontWeight:700}}>
              <span style={{color:accent}}><Num>{nf(todayTopics.filter(x=>x.done).length)}</Num> {t.doneCount}</span>
              <span style={{color:textMuted2, opacity:0.5}}>|</span>
              <span style={{color:textMuted2}}><Num>{nf(todayTopics.length - todayTopics.filter(x=>x.done).length)}</Num> {t.remaining}</span>
            </div>
            <div style={{marginTop:10, height:6, width:150, borderRadius:4, background: dark?"#37332C":"#EFE9DC", overflow:"hidden"}}>
              <div style={{height:"100%", width:`${todayTopics.length ? Math.round((todayTopics.filter(x=>x.done).length/todayTopics.length)*100) : 0}%`, background:accent, borderRadius:4, transition:"width .3s"}}/>
            </div>
          </div>
          <PercentRing pct={todayTopics.length ? Math.round((todayTopics.filter(x=>x.done).length/todayTopics.length)*100) : 0}
            accent={accent} trackColor={dark?"#37332C":"#EFE9DC"} textMain={textMain} nf={nf}/>
        </div>
        )}

        {/* Today's study list - Today tab only */}
        {tab === "today" && (
        <div style={{marginTop:20}}>
          <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:12}}>
            <div style={{fontSize:22, fontWeight:800}}>{t.todaysStudy}</div>
            <button onClick={()=>{setAddTargetKey(todayKey); setShowAdd(true);}} style={{display:"flex",alignItems:"center",gap:5, background: dark? "#F3EFE7":"#211D18", color: dark?"#211D18":"#F3EFE7", border:"none", borderRadius:12, padding:"9px 13px", fontSize:12, fontWeight:700, cursor:"pointer"}}>
              <Plus size={14}/> {t.addTopic}
            </button>
          </div>

          <TopicsList items={todayTopics} allSubjects={allSubjects} t={t} nf={nf} lang={lang}
            cardBg={cardBg} cardBorder={cardBorder} textMuted2={textMuted2}
            onToggle={(id)=>toggleDoneFor(todayKey, id)} onStartTimer={startTimerFor}
            onEdit={(item)=>setEditTopic({...item, _dk: todayKey})} onDelete={(id)=>deleteTopicFor(todayKey, id)}
            emptyText={t.noTopicsToday}/>
        </div>
        )}

        {/* TODAY tab */}
        {tab === "today" && (
          <div style={{marginTop:20}}>
            {/* week strip */}
            <div>

              <div onClick={()=>setWeekExpanded(v=>!v)} style={{display:"flex", alignItems:"center", gap:4, cursor:"pointer", marginBottom:10}}>
                <span style={{fontSize:10, letterSpacing:ls(1.5), color:textMuted2, fontWeight:700}}>{t.thisWeek}</span>
                <ChevronRight size={12} color={textMuted2} style={{transform: weekExpanded ? "rotate(90deg)" : "none", transition:"transform .2s"}}/>
              </div>
              <div style={{display:"flex", justifyContent:"space-between", background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:16, padding:"12px 6px"}}>
                {weekDays.map((d,i) => {
                  const dk = dateKey(d);
                  const isToday = dk === todayKey;
                  const list = entries[dk] || [];
                  const hasAny = list.length > 0;
                  const doneAll = hasAny && list.every(x=>x.done);
                  return (
                    <div key={i} onClick={()=>{vibrate(); setSelectedDay(d);}} style={{textAlign:"center", cursor:"pointer", flex:1}}>
                      <div style={{fontSize:9, fontWeight:700, color:textMuted2, marginBottom:6}}>{weekdayShort(d)}</div>
                      <div style={{width:30,height:30, borderRadius:"50%", display:"flex",alignItems:"center",justifyContent:"center", margin:"0 auto", fontSize:12, fontWeight:700,
                        background: isToday ? "#211D18" : "transparent", color: isToday ? "#F3EFE7" : textMain}}>
                        <Num>{nf(d.getDate())}</Num>
                      </div>
                      <div style={{width:5,height:5,borderRadius:"50%", margin:"5px auto 0", background: !hasAny ? "transparent" : (doneAll ? "#6E8B5E" : accent)}}/>
                    </div>
                  );
                })}
              </div>
              {weekExpanded && (
                <div style={{marginTop:12, background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:16, padding:"14px 16px"}}>
                  <SubjectGroupedList entries={weekEntries} nf={nf} t={t}
                    remainingLabel={t.remainingHeader} doneLabel={t.doneHeader}
                    remainingEmptyText={t.noneMissed} doneEmptyText={t.noneCovered}
                    cardBg={dark?"#1C1A17":"#F8F5EE"} cardBorder={cardBorder} textMuted2={textMuted2} accent={accent}/>
                </div>
              )}
            </div>

            {/* syllabus progress */}
            <div style={{marginTop:22}}>
              <div style={{display:"flex", justifyContent:"space-between", alignItems:"center"}}>
                <div>
                  <div style={{fontSize:10, letterSpacing:ls(1.5), color:textMuted2, fontWeight:700}}>{t.longView}</div>
                  <div style={{fontSize:19, fontWeight:800, marginTop:2}}>{t.syllabusProgress}</div>
                </div>
                <button onClick={()=>{vibrate(); setShowSubjects(true);}} style={{display:"flex",alignItems:"center",gap:4, border:`1px solid ${cardBorder}`, background:"transparent", color:textMuted2, borderRadius:10, padding:"7px 10px", fontSize:11, fontWeight:700, cursor:"pointer"}}>
                  <Plus size={12}/> {t.manageSubjects}
                </button>
              </div>
              <div style={{display:"flex", flexDirection:"column", gap:10, marginTop:12}}>
                {allSubjects.length === 0 && (
                  <div style={{fontSize:13, color:textMuted2, padding:"14px 0"}}>—</div>
                )}
                {allSubjects.map(subj => {
                  const v = subjectProgress[subj] || { done:0, total:0 };
                  const c = colorForSubject(subj, allSubjects);
                  const pct = v.total ? Math.round((v.done/v.total)*100) : 0;
                  return (
                    <div key={subj} style={{background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:16, padding:"14px 16px"}}>
                      <div style={{display:"flex", justifyContent:"space-between", marginBottom:8}}>
                        <span style={{fontWeight:700, fontSize:14}}>{subj}</span>
                        <span style={{fontSize:12, color:textMuted2, fontWeight:600}}><Num>{nf(v.done)}</Num> / <Num>{nf(v.total)}</Num></span>
                      </div>
                      <div style={{height:7, borderRadius:4, background: dark? "#37332C":"#EFE9DC", overflow:"hidden"}}>
                        <div style={{height:"100%", width:`${pct}%`, background:c.bg, borderRadius:4, transition:"width .3s"}}/>
                      </div>
                      <div style={{fontSize:11, fontWeight:700, color:c.bg, marginTop:6, letterSpacing:ls(0.5)}}><Num>{nf(pct)}</Num>% {t.complete}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {/* PLAN tab - next 7 days */}
        {tab === "plan" && (
          <div style={{marginTop:20}}>
            <div style={{fontSize:10, letterSpacing:ls(1.5), color:textMuted2, fontWeight:700, marginBottom:10}}>{t.next7Days}</div>
            <div style={{display:"flex", justifyContent:"space-between", background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:16, padding:"12px 6px"}}>
              {planDays.map((d,i) => {
                const dk = dateKey(d);
                const isSel = dk === planKey;
                const count = (entries[dk] || []).length;
                return (
                  <div key={i} onClick={()=>setPlanDate(d)} style={{textAlign:"center", cursor:"pointer", flex:1}}>
                    <div style={{fontSize:9, fontWeight:700, color:textMuted2, marginBottom:6}}>{weekdayShort(d)}</div>
                    <div style={{width:30,height:30, borderRadius:"50%", display:"flex",alignItems:"center",justifyContent:"center", margin:"0 auto", fontSize:12, fontWeight:700,
                      background: isSel ? accent : "transparent", color: isSel ? "#fff" : textMain}}>
                      <Num>{nf(d.getDate())}</Num>
                    </div>
                    <div style={{fontSize:9, color:textMuted2, marginTop:5, fontWeight:700}}>{count > 0 ? <Num>{nf(count)}</Num> : "·"}</div>
                  </div>
                );
              })}
            </div>

            <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginTop:20, marginBottom:12}}>
              <div style={{fontSize:19, fontWeight:800}}>
                {isPlanToday ? t.todaysStudy : <>{weekdayName(planDate)}, <Num>{nf(planDate.getDate())}</Num> {monthName(planDate.getMonth())}</>}
              </div>
              <button onClick={()=>{setAddTargetKey(planKey); setShowAdd(true);}} style={{display:"flex",alignItems:"center",gap:5, background: dark? "#F3EFE7":"#211D18", color: dark?"#211D18":"#F3EFE7", border:"none", borderRadius:12, padding:"9px 13px", fontSize:12, fontWeight:700, cursor:"pointer"}}>
                <Plus size={14}/> {t.addTopic}
              </button>
            </div>

            <TopicsList items={planTopics} allSubjects={allSubjects} t={t} nf={nf} lang={lang}
              cardBg={cardBg} cardBorder={cardBorder} textMuted2={textMuted2}
              onToggle={isPlanToday ? (id)=>toggleDoneFor(planKey, id) : null}
              onStartTimer={isPlanToday ? startTimerFor : null}
              onEdit={(item)=>setEditTopic({...item, _dk: planKey})}
              onDelete={(id)=>deleteTopicFor(planKey, id)}
              emptyText={t.noTopicsToday}/>
          </div>
        )}

        {/* WEEK tab - summary */}
        {tab === "week" && (
          <SummaryView t={t} lang={lang} nf={nf} entries={weekEntries} title={t.weeklySummary} mode="count"
            cardBg={cardBg} cardBorder={cardBorder} textMuted2={textMuted2} accent={accent} dark={dark}
            rangeLabel={<><Num>{nf(weekDays[0].getDate())}</Num> {monthName(weekDays[0].getMonth())} – <Num>{nf(weekDays[6].getDate())}</Num> {monthName(weekDays[6].getMonth())}</>}
            allSubjects={allSubjects}/>
        )}

        {/* MONTH tab - summary */}
        {tab === "month" && (
          <SummaryView t={t} lang={lang} nf={nf} entries={monthEntries} title={t.monthlySummary} mode="duration" crossWeekResolve
            cardBg={cardBg} cardBorder={cardBorder} textMuted2={textMuted2} accent={accent} dark={dark}
            rangeLabel={<>{monthName(today.getMonth())} <Num>{nf(today.getFullYear())}</Num></>}
            allSubjects={allSubjects}/>
        )}

        {/* EXAM tab - dedicated exam overview */}
        {tab === "exam" && (
          <div style={{marginTop:20}}>
            {/* Next exam card (manually set) */}
            <div style={{position:"relative", background: dark?"#2B2823":"#FBF3EC", border:`1px solid ${dark?"#3D372D":"#F0DCC9"}`, borderRadius:18, padding:"18px 18px 20px", textAlign:"center"}}>
              <div style={{position:"absolute", top:10, right:10, display:"flex", gap:4}}>
                <button onClick={()=>setShowNextExamEditor(true)} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2, padding:4}}><Pencil size={14}/></button>
                {nextExam && <button onClick={()=>setNextExam(null)} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2, padding:4}}><X size={15}/></button>}
              </div>
              <div style={{fontSize:10, letterSpacing:ls(1.5), color:textMuted2, fontWeight:700}}>{t.nextExamCard}</div>
              {nextExam ? (() => {
                const diff = Math.round((new Date(nextExam.date + "T00:00:00") - new Date(dateKey(today) + "T00:00:00")) / 86400000);
                return (
                  <>
                    <div style={{fontSize:16, fontWeight:800, marginTop:6}}>{nextExam.subject}{nextExam.topic ? ` · ${nextExam.topic}` : ""}</div>
                    <div style={{fontSize:42, fontWeight:800, color:accent, marginTop:6, lineHeight:1}}>
                      {diff === 0 ? t.examToday : (diff < 0 ? t.examPassed : <Num>{nf(diff)}</Num>)}
                    </div>
                    {diff > 0 && <div style={{fontSize:11, color:textMuted2, fontWeight:700, marginTop:4}}>{t.daysLeftLabel}</div>}
                  </>
                );
              })() : (
                <div style={{fontSize:13, color:textMuted2, marginTop:10}}>{t.noUpcomingExam}</div>
              )}
            </div>

            {/* My exams */}
            <div style={{marginTop:22}}>
              <div style={{display:"flex", justifyContent:"space-between", alignItems:"center"}}>
                <div style={{fontSize:19, fontWeight:800}}>{t.examSubjects}</div>
                <button onClick={()=>{vibrate(); setShowExams(true);}} style={{display:"flex",alignItems:"center",gap:4, border:`1px solid ${cardBorder}`, background:"transparent", color:textMuted2, borderRadius:10, padding:"7px 10px", fontSize:11, fontWeight:700, cursor:"pointer", flexShrink:0}}>
                  <Plus size={12}/> {t.manageExams}
                </button>
              </div>
              <div style={{display:"flex", flexDirection:"column", gap:18, marginTop:14}}>
                {Object.keys(examSubjects).length === 0 && (
                  <div style={{textAlign:"center", padding:"22px 10px", color:textMuted2, fontSize:13, background:cardBg, border:`1px dashed ${cardBorder}`, borderRadius:16}}>
                    {t.noExamSubjects}
                  </div>
                )}
                {Object.keys(examSubjects).sort((a,b)=>a.localeCompare(b)).map(subj => {
                  const c = colorForSubject(subj, allSubjects);
                  const topics = examSubjects[subj]?.topics || {};
                  return (
                    <div key={subj}>
                      <div style={{display:"flex", alignItems:"center", gap:7, marginBottom:8}}>
                        <span style={{width:8,height:8,borderRadius:"50%", background:c.bg, flexShrink:0}}/>
                        <span style={{fontWeight:700, fontSize:14}}>{subj}</span>
                      </div>
                      <div style={{display:"flex", flexDirection:"column", gap:8}}>
                        {Object.keys(topics).length === 0 && (
                          <div style={{fontSize:12, color:textMuted2, paddingLeft:15}}>{t.noTopicsInSubject}</div>
                        )}
                        {Object.entries(topics).map(([topicName, topicInfo]) => (
                          <TopicFolderCard key={topicName} subj={subj} topicName={topicName} attempts={topicInfo?.attempts || []}
                            t={t} nf={nf} lang={lang} cardBg={cardBg} cardBorder={cardBorder} textMuted2={textMuted2} accent={accent} dark={dark}
                            onAddAttempt={(date,obtained,total)=>addExamAttempt(subj,topicName,date,obtained,total)}
                            onRemoveAttempt={(attemptId)=>removeExamAttempt(subj,topicName,attemptId)}
                            onRemoveTopic={()=>removeExamTopic(subj,topicName)}/>
                        ))}
                        <AddTopicInline t={t} accent={accent} cardBorder={cardBorder} textMuted2={textMuted2} dark={dark}
                          onAdd={(name)=>addExamTopic(subj,name)}/>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Monthly summary */}
            <ExamMonthlySummary t={t} nf={nf} lang={lang} ls={ls} monthName={monthName} examSubjects={examSubjects}
              examMonth={examMonth} setExamMonth={setExamMonth} allSubjects={allSubjects}
              cardBg={cardBg} cardBorder={cardBorder} textMain={textMain} textMuted2={textMuted2} accent={accent} dark={dark}/>
          </div>
        )}
      </div>

      {/* Bottom nav */}
      <div style={{position:"sticky", left:0, right:0, bottom:0, display:"flex", justifyContent:"center", padding:"10px 16px 12px", zIndex:40, background: `linear-gradient(to top, ${bg} 60%, transparent)`}}>
        <div style={{width:"100%", maxWidth:480, display:"flex", background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:16, padding:"4px", boxShadow:"0 6px 18px rgba(0,0,0,0.10)"}}>
          {[
            {k:"today", Icon: Home},
            {k:"plan", Icon: CalendarDays},
            {k:"week", Icon: Calendar},
            {k:"month", Icon: BarChart3},
            {k:"exam", Icon: GraduationCap},
          ].map(({k, Icon}) => (
            <button key={k} onClick={()=>{vibrate(); setTab(k);}} style={{
              flex:1, display:"flex", flexDirection:"column", alignItems:"center", gap:2, border:"none", borderRadius:11, padding:"6px 4px", fontSize:9.5, fontWeight:700, cursor:"pointer",
              background: tab===k ? "rgba(217,119,87,0.15)" : "transparent",
              color: tab===k ? accent : textMuted2
            }}>
              <Icon size={15} strokeWidth={tab===k?2.3:2}/>
              {t.tabs[k]}
            </button>
          ))}
        </div>
      </div>

      {/* Fullscreen focus timer */}
      {focusFullscreen && (
        <FullscreenFocus
          t={t} nf={nf} mode={focusMode}
          seconds={focusMode === "timer" ? timerSeconds : stopwatchSeconds}
          total={timerTotal}
          running={focusMode === "timer" ? timerRunning : stopwatchRunning}
          topicLabel={timerTopic ? `${timerTopic.subject} · ${timerTopic.topic}` : (focusMode === "timer" ? t.freeSession : t.pickTopicForTimer)}
          accent={accent} dark={dark} bg={bg} textMain={textMain} textMuted2={textMuted2}
          onToggleRun={focusMode === "timer" ? toggleTimerRunning : toggleStopwatchRunning}
          onReset={()=>{
            if (focusMode === "timer") { setTimerRunning(false); setTimerSeconds(timerTotal); }
            else { setStopwatchRunning(false); setStopwatchSeconds(0); }
          }}
          onClose={()=>setFocusFullscreen(false)}
        />
      )}

      {/* Add topic modal */}
      {showAdd && (
        <AddModal t={t} nf={nf} subjects={subjects} defaultStart={`${pad2(now.getHours())}:${pad2(now.getMinutes())}`}
          onClose={()=>setShowAdd(false)} onAdd={addTopic}
          cardBg={cardBg} cardBorder={cardBorder} textMain={textMain} textMuted2={textMuted2} accent={accent} dark={dark}/>
      )}

      {/* Edit topic modal */}
      {editTopic && (
        <EditModal t={t} nf={nf} subjects={subjects} item={editTopic} onClose={()=>setEditTopic(null)} onSave={saveEditTopic} cardBg={cardBg} cardBorder={cardBorder} textMain={textMain} textMuted2={textMuted2} accent={accent} dark={dark}/>
      )}

      {/* Manage subjects modal */}
      {showSubjects && (
        <SubjectsModal t={t} subjects={subjects} onAdd={addSubject} onRemove={removeSubject} onClose={()=>setShowSubjects(false)}
          cardBg={cardBg} cardBorder={cardBorder} textMain={textMain} textMuted2={textMuted2} accent={accent} dark={dark}/>
      )}

      {/* Manage exams modal */}
      {showExams && (
        <ExamsModal t={t} nf={nf} subjects={allSubjects} examSubjects={examSubjects} onAdd={addExamSubject} onRemove={removeExamSubject} onClose={()=>setShowExams(false)}
          cardBg={cardBg} cardBorder={cardBorder} textMain={textMain} textMuted2={textMuted2} accent={accent} dark={dark}/>
      )}

      {/* Next exam editor modal */}
      {showNextExamEditor && (
        <NextExamModal t={t} examSubjects={examSubjects} nextExam={nextExam} onSave={(val)=>{setNextExam(val); setShowNextExamEditor(false);}}
          onClose={()=>setShowNextExamEditor(false)}
          cardBg={cardBg} cardBorder={cardBorder} textMain={textMain} textMuted2={textMuted2} accent={accent} dark={dark}/>
      )}

      {/* Calendar month view */}
      {showCalendar && (
        <CalendarModal t={t} lang={lang} nf={nf} monthName={monthName} weekdayShort={weekdayShort}
          calMonth={calMonth} setCalMonth={setCalMonth} entries={entries}
          onClose={()=>setShowCalendar(false)} onSelectDay={(d)=>{setSelectedDay(d); setShowCalendar(false);}}
          cardBg={cardBg} cardBorder={cardBorder} textMain={textMain} textMuted2={textMuted2} accent={accent} dark={dark} today={today}/>
      )}

      {/* Day detail modal */}
      {selectedDay && (
        <DayDetailModal t={t} lang={lang} nf={nf} weekdayName={weekdayName} monthName={monthName}
          day={selectedDay} entries={entries[dateKey(selectedDay)] || []} allSubjects={allSubjects}
          onClose={()=>setSelectedDay(null)} cardBg={cardBg} cardBorder={cardBorder} textMain={textMain} textMuted2={textMuted2} accent={accent} dark={dark}/>
      )}
    </div>
  );
}

// Big flip-clock-style digit block for the fullscreen focus timer.
function FlipBlock({ children, textMain, dark }) {
  return (
    <div style={{
      position:"relative",
      background: dark ? "#2B2823" : "#FFFFFF",
      border:`1px solid ${dark ? "#3D372D" : "#F0DCC9"}`,
      borderRadius:32,
      padding:"clamp(14px,3vw,28px) clamp(8px,1.5vw,16px)",
      width:"clamp(130px, 30vw, 260px)",
      textAlign:"center",
      overflow:"hidden",
      boxShadow: dark ? "none" : "0 6px 18px rgba(33,29,24,0.06)",
    }}>
      <div style={{
        fontFamily:"'Bebas Neue','Hind Siliguri',sans-serif",
        fontSize:"clamp(90px, 24vw, 210px)",
        fontWeight:400,
        lineHeight:0.85,
        color:textMain,
        fontVariantNumeric:"tabular-nums",
        letterSpacing:2,
      }}>
        {children}
      </div>
      <div style={{position:"absolute", left:0, right:0, top:"50%", height:1, background: dark ? "rgba(0,0,0,0.35)" : "rgba(33,29,24,0.08)"}}/>
    </div>
  );
}

// Fullscreen focus session view, entered when the timer/stopwatch is started.
// Keeps the app's own color palette (light/dark) rather than a hardcoded theme.
function FullscreenFocus({ t, nf, mode, seconds, total, running, topicLabel, accent, dark, bg, textMain, textMuted2, onToggleRun, onReset, onClose }) {
  const mm = pad2(Math.floor(Math.max(0,seconds)/60));
  const ss = pad2(Math.max(0,seconds)%60);
  const pct = mode === "timer" && total ? Math.min(100, Math.max(0, Math.round(((total-seconds)/total)*100))) : null;

  return (
    <div style={{position:"fixed", inset:0, zIndex:100, background:bg, color:textMain, display:"flex", flexDirection:"column"}}>
      <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", padding:"20px 20px 0"}}>
        <button onClick={onClose} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2, display:"flex", alignItems:"center", padding:6}}>
          <ChevronDown size={22}/>
        </button>
        <span style={{fontSize:11, letterSpacing:2, fontWeight:700, color:textMuted2}}>
          {mode === "timer" ? t.focusTimer : t.stopwatchMode.toUpperCase()}
        </span>
        <div style={{width:34}}/>
      </div>

      <div style={{flex:1, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:26, padding:"0 24px"}}>
        <div style={{fontSize:14, fontWeight:700, color:accent, textAlign:"center", maxWidth:280}}>{topicLabel}</div>

        <div style={{display:"flex", alignItems:"center", gap:"clamp(4px,1vw,10px)"}}>
          <FlipBlock textMain={textMain} dark={dark}>{nf(mm)}</FlipBlock>
          <div style={{fontFamily:"'Bebas Neue','Hind Siliguri',sans-serif", fontSize:"clamp(55px,11vw,100px)", fontWeight:400, color:textMuted2, marginBottom:6}}>:</div>
          <FlipBlock textMain={textMain} dark={dark}>{nf(ss)}</FlipBlock>
        </div>

        {pct !== null && (
          <div style={{height:6, width:220, borderRadius:4, background: dark?"#37332C":"#EFE9DC", overflow:"hidden"}}>
            <div style={{height:"100%", width:`${pct}%`, background:accent, borderRadius:4, transition:"width .3s"}}/>
          </div>
        )}
      </div>

      <div style={{display:"flex", gap:14, padding:"0 30px 48px", justifyContent:"center"}}>
        <button onClick={onToggleRun} style={{flex:1, maxWidth:240, background:accent, border:"none", borderRadius:16, padding:"16px 0", color:"#fff", fontWeight:700, fontSize:16, display:"flex",alignItems:"center",justifyContent:"center", gap:8, cursor:"pointer"}}>
          {running ? <Pause size={18} fill="#fff"/> : <Play size={18} fill="#fff"/>} {running ? t.pause : t.start}
        </button>
        <button onClick={onReset} style={{background: dark?"#3D372D":"#F0DCC9", border:"none", borderRadius:16, width:56, display:"flex",alignItems:"center",justifyContent:"center", cursor:"pointer"}}>
          <RotateCcw size={20} color={textMain}/>
        </button>
      </div>
    </div>
  );
}
function PercentRing({ pct, size = 56, stroke = 5, accent, trackColor, textMain, nf }) {
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  const offset = c - (Math.min(100, Math.max(0, pct)) / 100) * c;
  return (
    <svg width={size} height={size} style={{transform:"rotate(-90deg)", flexShrink:0}}>
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={trackColor} strokeWidth={stroke}/>
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={accent} strokeWidth={stroke}
        strokeDasharray={c} strokeDashoffset={offset} strokeLinecap="round" style={{transition:"stroke-dashoffset .3s"}}/>
      <text x="50%" y="50%" fill={textMain} fontSize={size*0.24} fontWeight={800}
        textAnchor="middle" dominantBaseline="central" style={{transform:`rotate(90deg)`, transformOrigin:"center"}}>
        <tspan>{nf(pct)}%</tspan>
      </text>
    </svg>
  );
}

function TopicFolderCard({ subj, topicName, attempts, t, nf, lang, cardBg, cardBorder, textMuted2, accent, dark, onAddAttempt, onRemoveAttempt, onRemoveTopic }) {
  const ls = (px) => (lang === "bn" ? 0 : px);
  const [expanded, setExpanded] = useState(false);
  const [date, setDate] = useState(() => { const d = new Date(); return dateKey(d); });
  const [obtained, setObtained] = useState("");
  const [total, setTotal] = useState("");
  const green = "#6E8B5E";

  const avgPct = attempts.length
    ? Math.round(attempts.reduce((sum, s) => sum + (s.total ? (s.obtained / s.total) * 100 : 0), 0) / attempts.length)
    : null;
  const completed = attempts.length > 0;

  const submitAttempt = () => {
    const o = parseFloat(obtained), tt = parseFloat(total);
    if (!isFinite(o) || !isFinite(tt) || tt <= 0) return;
    onAddAttempt(date, o, tt);
    setObtained(""); setTotal("");
  };

  const smallInput = { width:56, border:`1px solid ${cardBorder}`, borderRadius:8, padding:"6px 8px", fontSize:12, background: dark?"#1C1A17":"#F8F5EE", color: dark?"#F3EFE7":"#211D18", outline:"none" };
  const dateInput = { border:`1px solid ${cardBorder}`, borderRadius:8, padding:"6px 8px", fontSize:12, background: dark?"#1C1A17":"#F8F5EE", color: dark?"#F3EFE7":"#211D18", outline:"none", flex:1 };

  return (
    <div style={{background: completed ? (dark?"rgba(110,139,94,0.10)":"rgba(110,139,94,0.07)") : cardBg, border: completed ? `1px solid rgba(110,139,94,0.4)` : `1px solid ${cardBorder}`, borderRadius:16, padding:"12px 14px"}}>
      <button onClick={()=>setExpanded(x=>!x)} style={{width:"100%", border:"none", background:"transparent", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"space-between", padding:0, color:"inherit", textAlign:"left"}}>
        <div style={{display:"flex", alignItems:"center", gap:8, minWidth:0}}>
          <Folder size={14} style={{color:textMuted2, flexShrink:0}}/>
          <span style={{fontWeight:700, fontSize:13.5, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis"}}>{topicName}</span>
        </div>
        <div style={{display:"flex", alignItems:"center", gap:6, flexShrink:0}}>
          {completed ? (
            <span style={{fontSize:10.5, fontWeight:700, color:green, background: dark?"rgba(110,139,94,0.18)":"rgba(110,139,94,0.15)", padding:"3px 8px", borderRadius:20, display:"flex", alignItems:"center", gap:3}}>
              <Check size={10}/> {t.completedBadge}
            </span>
          ) : (
            <span style={{fontSize:11, color:textMuted2, fontWeight:600}}>{t.noAttemptsYet}</span>
          )}
          <ChevronDown size={15} style={{color:textMuted2, transform: expanded ? "rotate(180deg)" : "none", transition:"transform .15s"}}/>
        </div>
      </button>

      {attempts.length > 0 && (
        <div style={{display:"flex", gap:10, marginTop:8, paddingLeft:22, fontSize:11.5, color:textMuted2, fontWeight:600}}>
          <span><Num>{nf(attempts.length)}</Num> {t.attemptsLabel}</span>
          {avgPct !== null && <span style={{color:accent, fontWeight:700}}>{t.average} <Num>{nf(avgPct)}</Num>%</span>}
        </div>
      )}

      {expanded && (
        <div style={{marginTop:12, paddingTop:12, borderTop:`1px dashed ${cardBorder}`}}>
          {attempts.length === 0 ? (
            <div style={{fontSize:12, color:textMuted2, marginBottom:8}}>{t.noAttemptsYet}</div>
          ) : (
            <div style={{display:"flex", flexDirection:"column", gap:6, marginBottom:10}}>
              {[...attempts].sort((a,b)=>(a.date||"").localeCompare(b.date||"")).map(a => (
                <div key={a.id} style={{display:"flex", justifyContent:"space-between", alignItems:"center"}}>
                  <span style={{fontSize:12.5, fontWeight:600}}>
                    {a.date && <span style={{color:textMuted2, fontWeight:500, marginRight:6}}>{a.date}</span>}
                    <Num>{nf(a.obtained)}</Num> / <Num>{nf(a.total)}</Num>
                    <span style={{color:textMuted2, fontWeight:500}}> (<Num>{nf(a.total ? Math.round((a.obtained/a.total)*100) : 0)}</Num>%)</span>
                  </span>
                  <button onClick={()=>onRemoveAttempt(a.id)} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2, display:"flex"}}>
                    <Trash2 size={13}/>
                  </button>
                </div>
              ))}
            </div>
          )}

          <div style={{display:"flex", alignItems:"center", gap:6, marginBottom:10}}>
            <input type="date" value={date} onChange={e=>setDate(e.target.value)} style={dateInput}/>
            <input type="number" inputMode="decimal" placeholder={t.obtainedPlaceholder} value={obtained} onChange={e=>setObtained(e.target.value)} style={smallInput}/>
            <span style={{color:textMuted2, fontSize:12, fontWeight:700}}>/</span>
            <input type="number" inputMode="decimal" placeholder={t.outOfPlaceholder} value={total} onChange={e=>setTotal(e.target.value)} style={smallInput}/>
            <button onClick={submitAttempt} style={{border:"none", borderRadius:8, width:30, height:30, background:accent, color:"#fff", display:"flex", alignItems:"center", justifyContent:"center", cursor:"pointer", flexShrink:0}}>
              <Plus size={15}/>
            </button>
          </div>

          <button onClick={onRemoveTopic} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2, fontSize:11, fontWeight:700, display:"flex", alignItems:"center", gap:4, padding:0}}>
            <Trash2 size={12}/> {t.deleteTopic}
          </button>
        </div>
      )}
    </div>
  );
}

function AddTopicInline({ t, accent, cardBorder, textMuted2, dark, onAdd }) {
  const [adding, setAdding] = useState(false);
  const [name, setName] = useState("");
  const submit = () => {
    const v = name.trim();
    if (!v) { setAdding(false); return; }
    onAdd(v);
    setName(""); setAdding(false);
  };
  if (!adding) {
    return (
      <button onClick={()=>setAdding(true)} style={{display:"flex", alignItems:"center", gap:4, border:`1px dashed ${cardBorder}`, background:"transparent", color:textMuted2, borderRadius:12, padding:"9px 12px", fontSize:12, fontWeight:700, cursor:"pointer", alignSelf:"flex-start"}}>
        <Plus size={12}/> {t.addTopicBtn}
      </button>
    );
  }
  return (
    <div style={{display:"flex", alignItems:"center", gap:6}}>
      <input autoFocus value={name} onChange={e=>setName(e.target.value)} onKeyDown={e=>{if(e.key==="Enter") submit(); if(e.key==="Escape"){setAdding(false); setName("");}}}
        placeholder={t.topicNamePlaceholder}
        style={{flex:1, border:`1px solid ${cardBorder}`, borderRadius:8, padding:"7px 10px", fontSize:12.5, background: dark?"#1C1A17":"#F8F5EE", color: dark?"#F3EFE7":"#211D18", outline:"none"}}/>
      <button onClick={submit} style={{border:"none", borderRadius:8, width:30, height:30, background:accent, color:"#fff", display:"flex", alignItems:"center", justifyContent:"center", cursor:"pointer", flexShrink:0}}>
        <Check size={15}/>
      </button>
    </div>
  );
}

function NextExamModal({ t, examSubjects, nextExam, onSave, onClose, cardBg, cardBorder, textMain, textMuted2, accent, dark }) {
  const subjectNames = Object.keys(examSubjects);
  const [subject, setSubject] = useState(nextExam?.subject || subjectNames[0] || "");
  const [topic, setTopic] = useState(nextExam?.topic || "");
  const [date, setDate] = useState(nextExam?.date || "");
  const topicOptions = Object.keys(examSubjects[subject]?.topics || {});

  const inputStyle = { border:`1px solid ${cardBorder}`, borderRadius:10, padding:"10px 12px", fontSize:13.5, background: dark?"#1C1A17":"#F8F5EE", color: dark?"#F3EFE7":"#211D18", outline:"none", width:"100%" };

  const submit = () => {
    if (!subject || !date) return;
    onSave({ subject, topic: topic.trim(), date });
  };

  return (
    <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,0.45)", display:"flex", alignItems:"flex-end", justifyContent:"center", zIndex:50}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:cardBg, width:"100%", maxWidth:480, borderRadius:"22px 22px 0 0", padding:"20px 20px 28px", color:textMain, display:"flex", flexDirection:"column", gap:14}}>
        <div style={{display:"flex", justifyContent:"space-between", alignItems:"center"}}>
          <div style={{fontSize:16, fontWeight:800}}>{t.setNextExam}</div>
          <button onClick={onClose} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2}}><X size={20}/></button>
        </div>

        {subjectNames.length === 0 ? (
          <div style={{fontSize:13, color:textMuted2, textAlign:"center", padding:"10px 0"}}>{t.noSubjectsForExam}</div>
        ) : (
          <>
            <div>
              <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.chooseSubject}</div>
              <select style={inputStyle} value={subject} onChange={e=>{setSubject(e.target.value); setTopic("");}}>
                {subjectNames.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <div>
              <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.chooseTopic}</div>
              <input style={inputStyle} list="next-exam-topics" value={topic} onChange={e=>setTopic(e.target.value)} placeholder={t.topicNamePlaceholder}/>
              <datalist id="next-exam-topics">
                {topicOptions.map(tp => <option key={tp} value={tp}/>)}
              </datalist>
            </div>
            <div>
              <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.examDateLabel}</div>
              <input type="date" style={inputStyle} value={date} onChange={e=>setDate(e.target.value)}/>
            </div>
            <button onClick={submit} style={{border:"none", borderRadius:12, padding:"12px 0", background:accent, color:"#fff", fontWeight:700, cursor:"pointer"}}>
              {t.save}
            </button>
          </>
        )}
      </div>
    </div>
  );
}

function ExamMonthlySummary({ t, nf, lang, ls, monthName, examSubjects, examMonth, setExamMonth, allSubjects, cardBg, cardBorder, textMain, textMuted2, accent, dark }) {
  const y = examMonth.getFullYear(), m = examMonth.getMonth();
  const prefix = `${y}-${pad2(m+1)}`;

  const perSubject = {};
  let totalAttempts = 0, totalScorePct = 0, maxScorePct = 0;
  const examTopicSet = new Set();

  Object.entries(examSubjects).forEach(([subj, info]) => {
    Object.entries(info?.topics || {}).forEach(([topicName, topicInfo]) => {
      (topicInfo?.attempts || []).forEach(a => {
        if (!a.date || !a.date.startsWith(prefix)) return;
        const pct = a.total ? (a.obtained/a.total)*100 : 0;
        totalAttempts += 1;
        totalScorePct += pct;
        if (pct > maxScorePct) maxScorePct = pct;
        examTopicSet.add(`${subj}::${topicName}`);
        if (!perSubject[subj]) perSubject[subj] = { attempts:0, scoreSum:0, topics:new Set() };
        perSubject[subj].attempts += 1;
        perSubject[subj].scoreSum += pct;
        perSubject[subj].topics.add(topicName);
      });
    });
  });

  const avgScorePct = totalAttempts ? Math.round(totalScorePct/totalAttempts) : null;
  const totalExams = examTopicSet.size;
  const rows = Object.entries(perSubject).sort((a,b)=>a[0].localeCompare(b[0]));

  const statBox = { background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:14, padding:"12px 14px" };

  return (
    <div style={{marginTop:26}}>
      <div style={{display:"flex", justifyContent:"space-between", alignItems:"center"}}>
        <div style={{fontSize:17, fontWeight:800}}>{t.monthlySummaryExam}</div>
        <div style={{display:"flex", alignItems:"center", gap:6}}>
          <button onClick={()=>setExamMonth(new Date(y,m-1,1))} style={{border:`1px solid ${cardBorder}`, background:"transparent", borderRadius:9, width:28,height:28, display:"flex",alignItems:"center",justifyContent:"center", cursor:"pointer", color:textMain}}><ChevronLeft size={14}/></button>
          <div style={{fontSize:12.5, fontWeight:700, minWidth:76, textAlign:"center"}}>{monthName(m)} <Num>{nf(y)}</Num></div>
          <button onClick={()=>setExamMonth(new Date(y,m+1,1))} style={{border:`1px solid ${cardBorder}`, background:"transparent", borderRadius:9, width:28,height:28, display:"flex",alignItems:"center",justifyContent:"center", cursor:"pointer", color:textMain}}><ChevronRight size={14}/></button>
        </div>
      </div>

      {totalAttempts === 0 ? (
        <div style={{textAlign:"center", padding:"22px 10px", color:textMuted2, fontSize:13, background:cardBg, border:`1px dashed ${cardBorder}`, borderRadius:16, marginTop:14}}>
          {t.noExamDataMonth}
        </div>
      ) : (
        <>
          <div style={{display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginTop:14}}>
            <div style={statBox}>
              <div style={{fontSize:10.5, color:textMuted2, fontWeight:700, letterSpacing:ls(0.5)}}>{t.totalExams}</div>
              <div style={{fontSize:22, fontWeight:800, marginTop:4}}><Num>{nf(totalExams)}</Num></div>
            </div>
            <div style={statBox}>
              <div style={{fontSize:10.5, color:textMuted2, fontWeight:700, letterSpacing:ls(0.5)}}>{t.totalAttempts}</div>
              <div style={{fontSize:22, fontWeight:800, marginTop:4}}><Num>{nf(totalAttempts)}</Num></div>
            </div>
            <div style={statBox}>
              <div style={{fontSize:10.5, color:textMuted2, fontWeight:700, letterSpacing:ls(0.5)}}>{t.avgScoreLabel}</div>
              <div style={{fontSize:22, fontWeight:800, marginTop:4, color:accent}}><Num>{nf(avgScorePct)}</Num>%</div>
            </div>
            <div style={statBox}>
              <div style={{fontSize:10.5, color:textMuted2, fontWeight:700, letterSpacing:ls(0.5)}}>{t.maxScoreLabel}</div>
              <div style={{fontSize:22, fontWeight:800, marginTop:4, color:"#6E8B5E"}}><Num>{nf(Math.round(maxScorePct))}</Num>%</div>
            </div>
          </div>

          <div style={{marginTop:16}}>
            <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:8}}>{t.subjectBreakdown}</div>
            <div style={{border:`1px solid ${cardBorder}`, borderRadius:14, overflow:"hidden"}}>
              <div style={{display:"grid", gridTemplateColumns:"1.6fr 0.8fr 0.8fr 0.8fr", padding:"8px 12px", background: dark?"#1C1A17":"#F8F5EE", fontSize:10.5, fontWeight:700, color:textMuted2}}>
                <span>{t.subjectLabel}</span><span style={{textAlign:"right"}}>{t.examsCol}</span><span style={{textAlign:"right"}}>{t.attemptsCol}</span><span style={{textAlign:"right"}}>{t.avgCol}</span>
              </div>
              {rows.map(([subj, d]) => {
                const c = colorForSubject(subj, allSubjects);
                const avg = Math.round(d.scoreSum/d.attempts);
                return (
                  <div key={subj} style={{display:"grid", gridTemplateColumns:"1.6fr 0.8fr 0.8fr 0.8fr", padding:"9px 12px", fontSize:12.5, fontWeight:600, borderTop:`1px solid ${cardBorder}`, alignItems:"center"}}>
                    <span style={{display:"flex", alignItems:"center", gap:6, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap"}}>
                      <span style={{width:7,height:7,borderRadius:"50%", background:c.bg, flexShrink:0}}/>{subj}
                    </span>
                    <span style={{textAlign:"right"}}><Num>{nf(d.topics.size)}</Num></span>
                    <span style={{textAlign:"right"}}><Num>{nf(d.attempts)}</Num></span>
                    <span style={{textAlign:"right", color:accent, fontWeight:700}}><Num>{nf(avg)}</Num>%</span>
                  </div>
                );
              })}
            </div>
          </div>
        </>
      )}
    </div>
  );
}


function SummaryView({ t, lang, nf, entries, title, rangeLabel, cardBg, cardBorder, textMuted2, accent, dark, allSubjects, mode, crossWeekResolve }) {
  const ls = (px) => (lang === "bn" ? 0 : px);
  // Subject-level catch-up: if a subject has any completed entry in this range,
  // its not-yet-done entries in the same range are treated as caught up too.
  const doneSubjects = new Set(entries.filter(e => e.done).map(e => e.subject));
  const effectiveEntries = entries.map(e => {
    if (!e.done && crossWeekResolve && doneSubjects.has(e.subject)) {
      return { ...e, done: true, _caughtUp: true };
    }
    return e;
  });

  const totalCount = effectiveEntries.length;
  const doneCount = effectiveEntries.filter(e => e.done).length;
  const overallPct = totalCount ? Math.round((doneCount/totalCount)*100) : 0;
  const trackColor = dark ? "#37332C" : "#EFE9DC";

  const subjTotals = {};
  effectiveEntries.forEach(e => {
    if (!subjTotals[e.subject]) subjTotals[e.subject] = { done:0, total:0 };
    subjTotals[e.subject].total += 1;
    if (e.done) subjTotals[e.subject].done += 1;
  });

  const subjMinutes = {};
  effectiveEntries.filter(e => e.done).forEach(e => {
    subjMinutes[e.subject] = (subjMinutes[e.subject] || 0) + (e.duration || 0);
  });
  const maxMinutes = Math.max(1, ...Object.values(subjMinutes).length ? Object.values(subjMinutes) : [0]);

  return (
    <div style={{marginTop:20}}>
      <div style={{fontSize:19, fontWeight:800}}>{title}</div>
      <div style={{fontSize:12, color:textMuted2, marginBottom:16, fontWeight:600}}>{rangeLabel}</div>

      {/* Overview card */}
      <div style={{display:"flex", alignItems:"center", justifyContent:"space-between", background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:16, padding:"14px 16px", marginBottom:20}}>
        <div>
          <div style={{fontSize:10, letterSpacing:ls(1.5), color:textMuted2, fontWeight:700, marginBottom:8}}>{t.overview}</div>
          <div style={{display:"flex", gap:16}}>
            <div>
              <div style={{fontSize:20, fontWeight:800, color:accent}}><Num>{nf(doneCount)}</Num></div>
              <div style={{fontSize:11, color:textMuted2, fontWeight:600}}>{t.doneCount}</div>
            </div>
            <div>
              <div style={{fontSize:20, fontWeight:800}}><Num>{nf(totalCount - doneCount)}</Num></div>
              <div style={{fontSize:11, color:textMuted2, fontWeight:600}}>{t.remaining}</div>
            </div>
          </div>
          <div style={{marginTop:10, height:6, width:120, borderRadius:4, background:trackColor, overflow:"hidden"}}>
            <div style={{height:"100%", width:`${overallPct}%`, background:accent, borderRadius:4, transition:"width .3s"}}/>
          </div>
        </div>
        <PercentRing pct={overallPct} accent={accent} trackColor={trackColor} textMain={dark?"#F3EFE7":"#211D18"} nf={nf}/>
      </div>

      {mode === "duration" ? (
        <div style={{marginBottom:20}}>
          <div style={{fontSize:10, letterSpacing:ls(1.5), color:textMuted2, fontWeight:700, marginBottom:10}}>{t.subjectTimeBreakdown}</div>
          <div style={{display:"flex", flexDirection:"column", gap:10}}>
            {Object.keys(subjMinutes).length === 0 && <div style={{fontSize:13, color:textMuted2}}>{t.noTimeData}</div>}
            {Object.entries(subjMinutes).sort((a,b)=>b[1]-a[1]).map(([subj, mins]) => {
              const c = colorForSubject(subj, allSubjects);
              const pct = Math.round((mins/maxMinutes)*100);
              return (
                <div key={subj} style={{background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:16, padding:"12px 16px"}}>
                  <div style={{display:"flex", justifyContent:"space-between", marginBottom:6}}>
                    <span style={{fontWeight:700, fontSize:13}}>{subj}</span>
                    <span style={{fontSize:12, fontWeight:700, color:c.bg}}>{formatDuration(mins, lang, nf)}</span>
                  </div>
                  <div style={{height:6, borderRadius:4, background: dark? "#37332C":"#EFE9DC", overflow:"hidden"}}>
                    <div style={{height:"100%", width:`${pct}%`, background:c.bg, borderRadius:4}}/>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ) : (
        <div style={{display:"flex", flexDirection:"column", gap:10, marginBottom:20}}>
          {Object.entries(subjTotals).length === 0 && <div style={{fontSize:13, color:textMuted2}}>—</div>}
          {Object.entries(subjTotals).map(([subj,v]) => {
            const c = colorForSubject(subj, allSubjects);
            const pct = v.total ? Math.round((v.done/v.total)*100) : 0;
            return (
              <div key={subj} style={{background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:16, padding:"12px 16px"}}>
                <div style={{display:"flex", justifyContent:"space-between", marginBottom:6}}>
                  <span style={{fontWeight:700, fontSize:13}}>{subj}</span>
                  <span style={{fontSize:12, fontWeight:700, color:c.bg}}><Num>{nf(pct)}</Num>%</span>
                </div>
                <div style={{height:6, borderRadius:4, background: dark? "#37332C":"#EFE9DC", overflow:"hidden"}}>
                  <div style={{height:"100%", width:`${pct}%`, background:c.bg, borderRadius:4}}/>
                </div>
              </div>
            );
          })}
        </div>
      )}

      <SubjectGroupedList entries={effectiveEntries} nf={nf} t={t}
        remainingLabel={t.missed} doneLabel={t.covered}
        remainingEmptyText={t.noneMissed} doneEmptyText={t.noneCovered}
        cardBg={cardBg} cardBorder={cardBorder} textMuted2={textMuted2} accent={accent}/>
    </div>
  );
}

// Read-only subject-grouped list: remaining topics first, then done topics.
function SubjectGroupedList({ entries, nf, t, remainingLabel, doneLabel, remainingEmptyText, doneEmptyText, cardBg, cardBorder, textMuted2, accent }) {
  const remaining = {}, done = {};
  entries.forEach(e => {
    const bucket = e.done ? done : remaining;
    if (!bucket[e.subject]) bucket[e.subject] = [];
    bucket[e.subject].push(e);
  });
  const remainingSubjects = Object.keys(remaining);
  const doneSubjects = Object.keys(done);
  const remainingCount = remainingSubjects.reduce((a,s)=>a+remaining[s].length, 0);
  const doneCount = doneSubjects.reduce((a,s)=>a+done[s].length, 0);
  return (
    <div style={{display:"flex", flexDirection:"column", gap:18}}>
      <div>
        <div style={{fontSize:12, fontWeight:700, color:accent, marginBottom:8}}>✕ {remainingLabel} (<Num>{nf(remainingCount)}</Num>)</div>
        {remainingSubjects.length === 0 ? <div style={{fontSize:12, color:textMuted2}}>{remainingEmptyText}</div> :
          <div style={{display:"flex", flexDirection:"column", gap:10}}>
            {remainingSubjects.map(subj => (
              <div key={subj}>
                <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:4}}>{subj}</div>
                <div style={{display:"flex", flexDirection:"column", gap:6}}>
                  {remaining[subj].map(e => (
                    <div key={e.id+(e._dk||"")} style={{background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:12, padding:"9px 12px", fontSize:13}}>{e.topic}</div>
                  ))}
                </div>
              </div>
            ))}
          </div>}
      </div>
      <div>
        <div style={{fontSize:12, fontWeight:700, color:"#6E8B5E", marginBottom:8}}>✓ {doneLabel} (<Num>{nf(doneCount)}</Num>)</div>
        {doneSubjects.length === 0 ? <div style={{fontSize:12, color:textMuted2}}>{doneEmptyText}</div> :
          <div style={{display:"flex", flexDirection:"column", gap:10}}>
            {doneSubjects.map(subj => (
              <div key={subj}>
                <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:4}}>{subj}</div>
                <div style={{display:"flex", flexDirection:"column", gap:6}}>
                  {done[subj].map(e => (
                    <div key={e.id+(e._dk||"")} style={{background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:12, padding:"9px 12px", fontSize:13, display:"flex", alignItems:"center", justifyContent:"space-between", gap:8}}>
                      <span>{e.topic}</span>
                      {e._caughtUp && <span style={{fontSize:10, fontWeight:700, color:accent, flexShrink:0}}>{t?.caughtUpNote}</span>}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>}
      </div>
    </div>
  );
}

// Read-only-capable list of topics used by the Today and Plan tabs.
function TopicsList({ items, allSubjects, t, nf, lang, cardBg, cardBorder, textMuted2, onToggle, onStartTimer, onEdit, onDelete, emptyText }) {
  const ls = (px) => (lang === "bn" ? 0 : px);
  if (items.length === 0) {
    return (
      <div style={{textAlign:"center", padding:"30px 10px", color:textMuted2, fontSize:13, background:cardBg, border:`1px dashed ${cardBorder}`, borderRadius:16}}>
        {emptyText}
      </div>
    );
  }
  return (
    <div style={{display:"flex", flexDirection:"column", gap:10}}>
      {items.map(item => {
        const c = colorForSubject(item.subject, allSubjects);
        return (
          <div key={item.id} style={{background:cardBg, border:`1px solid ${cardBorder}`, borderRadius:16, padding:"12px 14px", display:"flex", alignItems:"center", gap:12}}>
            <button onClick={onToggle ? ()=>onToggle(item.id) : undefined} disabled={!onToggle}
              style={{width:34,height:34, borderRadius:"50%", border:"none", flexShrink:0, cursor: onToggle?"pointer":"default", background: item.done ? "#6E8B5E" : c.bgSoft, display:"flex",alignItems:"center",justifyContent:"center"}}>
              {item.done ? <Check size={16} color="#fff" strokeWidth={3}/> : <span style={{width:9,height:9,borderRadius:"50%", background:c.bg}}/>}
            </button>
            <div style={{flex:1, minWidth:0}} onClick={onStartTimer ? ()=>onStartTimer(item.id, item.duration) : undefined}>
              <div style={{fontSize:10, fontWeight:700, letterSpacing:ls(0.5), color:c.bg}}>{item.subject.toUpperCase()}</div>
              <div style={{fontSize:14, fontWeight:600, textDecoration: item.done ? "line-through":"none", opacity: item.done?0.55:1, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis"}}>{item.topic}</div>
            </div>
            <div style={{textAlign:"right", flexShrink:0}}>
              <div style={{fontSize:12, fontWeight:600, color:textMuted2}}>
                {item.time
                  ? (item.endTime ? <><Num>{nf(item.time)}</Num>–<Num>{nf(item.endTime)}</Num></> : <Num>{nf(item.time)}</Num>)
                  : t.noTimeSet}
              </div>
              <div style={{fontSize:11, color:textMuted2}}><Num>{nf(item.duration)}</Num> {t.minutes}</div>
            </div>
            {onEdit && (
              <button onClick={()=>onEdit(item)} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2, padding:2}}>
                <Pencil size={15}/>
              </button>
            )}
            {onDelete && (
              <button onClick={()=>onDelete(item.id)} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2, padding:2}}>
                <Trash2 size={15}/>
              </button>
            )}
          </div>
        );
      })}
    </div>
  );
}

function AddModal({ t, nf, subjects, defaultStart, onClose, onAdd, cardBg, cardBorder, textMain, textMuted2, accent, dark }) {
  const [subject, setSubject] = useState(subjects[0] || "");
  const [topic, setTopic] = useState("");
  const [useTime, setUseTime] = useState(false);
  const [startTime, setStartTime] = useState(defaultStart);
  const [endTime, setEndTime] = useState(minutesToTime(timeToMinutes(defaultStart) + 30));
  const [durationInput, setDurationInput] = useState(30);
  const inputStyle = { width:"100%", boxSizing:"border-box", background: dark?"#1C1A17":"#F8F5EE", border:`1px solid ${cardBorder}`, borderRadius:12, padding:"11px 13px", fontSize:14, color:textMain, outline:"none", fontFamily:"inherit" };
  const duration = useTime ? diffMinutes(startTime, endTime) : (Number(durationInput) || 0);
  const canSubmit = subjects.length > 0 && subject && topic.trim();
  return (
    <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,0.45)", display:"flex", alignItems:"flex-end", justifyContent:"center", zIndex:50}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:cardBg, width:"100%", maxWidth:480, borderRadius:"22px 22px 0 0", padding:"20px 20px 28px", color:textMain}}>
        <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:16}}>
          <div style={{fontSize:17, fontWeight:800}}>{t.addTopicTitle}</div>
          <button onClick={onClose} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2}}><X size={20}/></button>
        </div>
        <div style={{display:"flex", flexDirection:"column", gap:12}}>
          <div>
            <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.subjectLabel}</div>
            {subjects.length === 0 ? (
              <div style={{fontSize:13, color:textMuted2, padding:"6px 0"}}>{t.addSubjectsFirst}</div>
            ) : (
              <select style={inputStyle} value={subject} onChange={e=>setSubject(e.target.value)}>
                {subjects.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            )}
          </div>
          <div>
            <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.topicLabel}</div>
            <input style={inputStyle} value={topic} onChange={e=>setTopic(e.target.value)} placeholder={t.topicPlaceholder}/>
          </div>

          <label style={{display:"flex", alignItems:"center", gap:8, cursor:"pointer", userSelect:"none"}}>
            <input type="checkbox" checked={useTime} onChange={e=>setUseTime(e.target.checked)}
              style={{width:16, height:16, accentColor:accent, cursor:"pointer"}}/>
            <span style={{fontSize:13, fontWeight:600, color:textMain}}>{t.addTimeToggle}</span>
          </label>

          {useTime ? (
            <div style={{display:"flex", gap:10}}>
              <div style={{flex:1}}>
                <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.startTimeLabel}</div>
                <input type="time" style={inputStyle} value={startTime} onChange={e=>setStartTime(e.target.value)}/>
              </div>
              <div style={{flex:1}}>
                <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.endTimeLabel}</div>
                <input type="time" style={inputStyle} value={endTime} onChange={e=>setEndTime(e.target.value)}/>
              </div>
            </div>
          ) : (
            <div>
              <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.durationLabel}</div>
              <input type="number" min="1" style={inputStyle} value={durationInput} onChange={e=>setDurationInput(e.target.value)}/>
            </div>
          )}

          <div style={{fontSize:12, color:textMuted2, fontWeight:600}}><Num>{nf(duration)}</Num> {t.minutes}</div>
        </div>
        <div style={{display:"flex", gap:10, marginTop:20}}>
          <button onClick={onClose} style={{flex:1, padding:"12px 0", borderRadius:12, border:`1px solid ${cardBorder}`, background:"transparent", color:textMain, fontWeight:700, cursor:"pointer"}}>{t.cancel}</button>
          <button onClick={()=> canSubmit && onAdd({subject, topic:topic.trim(), time: useTime ? startTime : null, endTime: useTime ? endTime : null, duration})}
            style={{flex:1, padding:"12px 0", borderRadius:12, border:"none", background:accent, color:"#fff", fontWeight:700, cursor:"pointer", opacity: canSubmit?1:0.5}}>{t.add}</button>
        </div>
      </div>
    </div>
  );
}

function EditModal({ t, nf, subjects, item, onClose, onSave, cardBg, cardBorder, textMain, textMuted2, accent, dark }) {
  const subjectOptions = Array.from(new Set([item.subject, ...subjects]));
  const [subject, setSubject] = useState(item.subject);
  const [topic, setTopic] = useState(item.topic);
  const [useTime, setUseTime] = useState(!!item.time);
  const [startTime, setStartTime] = useState(item.time || "09:00");
  const [endTime, setEndTime] = useState(item.endTime || minutesToTime(timeToMinutes(item.time || "09:00") + (item.duration || 30)));
  const [durationInput, setDurationInput] = useState(item.duration || 30);
  const inputStyle = { width:"100%", boxSizing:"border-box", background: dark?"#1C1A17":"#F8F5EE", border:`1px solid ${cardBorder}`, borderRadius:12, padding:"11px 13px", fontSize:14, color:textMain, outline:"none", fontFamily:"inherit" };
  const duration = useTime ? diffMinutes(startTime, endTime) : (Number(durationInput) || 0);
  return (
    <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,0.45)", display:"flex", alignItems:"flex-end", justifyContent:"center", zIndex:50}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:cardBg, width:"100%", maxWidth:480, borderRadius:"22px 22px 0 0", padding:"20px 20px 28px", color:textMain}}>
        <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:16}}>
          <div style={{fontSize:17, fontWeight:800}}>{t.editTopicTitle}</div>
          <button onClick={onClose} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2}}><X size={20}/></button>
        </div>
        <div style={{display:"flex", flexDirection:"column", gap:12}}>
          <div>
            <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.subjectLabel}</div>
            <select style={inputStyle} value={subject} onChange={e=>setSubject(e.target.value)}>
              {subjectOptions.map(s => <option key={s} value={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.topicLabel}</div>
            <input style={inputStyle} value={topic} onChange={e=>setTopic(e.target.value)} placeholder={t.topicPlaceholder}/>
          </div>

          <label style={{display:"flex", alignItems:"center", gap:8, cursor:"pointer", userSelect:"none"}}>
            <input type="checkbox" checked={useTime} onChange={e=>setUseTime(e.target.checked)}
              style={{width:16, height:16, accentColor:accent, cursor:"pointer"}}/>
            <span style={{fontSize:13, fontWeight:600, color:textMain}}>{t.addTimeToggle}</span>
          </label>

          {useTime ? (
            <div style={{display:"flex", gap:10}}>
              <div style={{flex:1}}>
                <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.startTimeLabel}</div>
                <input type="time" style={inputStyle} value={startTime} onChange={e=>setStartTime(e.target.value)}/>
              </div>
              <div style={{flex:1}}>
                <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.endTimeLabel}</div>
                <input type="time" style={inputStyle} value={endTime} onChange={e=>setEndTime(e.target.value)}/>
              </div>
            </div>
          ) : (
            <div>
              <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.durationLabel}</div>
              <input type="number" min="1" style={inputStyle} value={durationInput} onChange={e=>setDurationInput(e.target.value)}/>
            </div>
          )}

          <div style={{fontSize:12, color:textMuted2, fontWeight:600}}><Num>{nf(duration)}</Num> {t.minutes}</div>
        </div>
        <div style={{display:"flex", gap:10, marginTop:20}}>
          <button onClick={onClose} style={{flex:1, padding:"12px 0", borderRadius:12, border:`1px solid ${cardBorder}`, background:"transparent", color:textMain, fontWeight:700, cursor:"pointer"}}>{t.cancel}</button>
          <button onClick={()=> subject && topic.trim() && onSave({id:item.id, subject, topic:topic.trim(), time: useTime ? startTime : null, endTime: useTime ? endTime : null, duration})}
            style={{flex:1, padding:"12px 0", borderRadius:12, border:"none", background:accent, color:"#fff", fontWeight:700, cursor:"pointer", opacity: (subject&&topic.trim())?1:0.5}}>{t.save}</button>
        </div>
      </div>
    </div>
  );
}

function SubjectsModal({ t, subjects, onAdd, onRemove, onClose, cardBg, cardBorder, textMain, textMuted2, accent, dark }) {
  const [name, setName] = useState("");
  const inputStyle = { width:"100%", boxSizing:"border-box", background: dark?"#1C1A17":"#F8F5EE", border:`1px solid ${cardBorder}`, borderRadius:12, padding:"11px 13px", fontSize:14, color:textMain, outline:"none", fontFamily:"inherit" };
  const submit = () => {
    const v = name.trim();
    if (!v || subjects.includes(v)) return;
    onAdd(v);
    setName("");
  };
  return (
    <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,0.45)", display:"flex", alignItems:"flex-end", justifyContent:"center", zIndex:50}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:cardBg, width:"100%", maxWidth:480, borderRadius:"22px 22px 0 0", padding:"20px 20px 28px", color:textMain, maxHeight:"75vh", display:"flex", flexDirection:"column"}}>
        <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:16}}>
          <div style={{fontSize:17, fontWeight:800}}>{t.manageSubjects}</div>
          <button onClick={onClose} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2}}><X size={20}/></button>
        </div>
        <div style={{display:"flex", gap:8, marginBottom:16}}>
          <input style={inputStyle} value={name} onChange={e=>setName(e.target.value)} placeholder={t.subjectPlaceholder}
            onKeyDown={e=>{ if (e.key === "Enter") submit(); }}/>
          <button onClick={submit} style={{border:"none", borderRadius:12, padding:"0 16px", background:accent, color:"#fff", fontWeight:700, cursor:"pointer"}}>{t.add}</button>
        </div>
        <div style={{overflowY:"auto", display:"flex", flexDirection:"column", gap:8}}>
          {subjects.length === 0 && <div style={{fontSize:13, color:textMuted2, textAlign:"center", padding:"20px 0"}}>{t.noSubjectsYet}</div>}
          {subjects.map(s => (
            <div key={s} style={{display:"flex", alignItems:"center", justifyContent:"space-between", border:`1px solid ${cardBorder}`, borderRadius:12, padding:"10px 14px"}}>
              <span style={{fontSize:14, fontWeight:600}}>{s}</span>
              <button onClick={()=>onRemove(s)} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2}}><Trash2 size={15}/></button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function ExamsModal({ t, nf, subjects, examSubjects, onAdd, onRemove, onClose, cardBg, cardBorder, textMain, textMuted2, accent, dark }) {
  const availableSubjects = subjects.filter(s => !examSubjects[s]);
  const [subject, setSubject] = useState(availableSubjects[0] || "");
  const inputStyle = { width:"100%", boxSizing:"border-box", background: dark?"#1C1A17":"#F8F5EE", border:`1px solid ${cardBorder}`, borderRadius:12, padding:"11px 13px", fontSize:14, color:textMain, outline:"none", fontFamily:"inherit" };
  const submit = () => {
    if (!subject) return;
    onAdd(subject);
    const next = availableSubjects.filter(s => s !== subject);
    setSubject(next[0] || "");
  };
  const examList = Object.entries(examSubjects);
  return (
    <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,0.45)", display:"flex", alignItems:"flex-end", justifyContent:"center", zIndex:50}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:cardBg, width:"100%", maxWidth:480, borderRadius:"22px 22px 0 0", padding:"20px 20px 28px", color:textMain, maxHeight:"80vh", display:"flex", flexDirection:"column"}}>
        <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:16}}>
          <div style={{fontSize:17, fontWeight:800}}>{t.manageExams}</div>
          <button onClick={onClose} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2}}><X size={20}/></button>
        </div>

        <div style={{display:"flex", flexDirection:"column", gap:10, marginBottom:16}}>
          {availableSubjects.length === 0 ? (
            <div style={{fontSize:13, color:textMuted2}}>{subjects.length === 0 ? t.addSubjectsFirst : "—"}</div>
          ) : (
            <>
              <div>
                <div style={{fontSize:11, fontWeight:700, color:textMuted2, marginBottom:6}}>{t.subjectLabel}</div>
                <select style={inputStyle} value={subject} onChange={e=>setSubject(e.target.value)}>
                  {availableSubjects.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <button onClick={submit} style={{border:"none", borderRadius:12, padding:"12px 0", background:accent, color:"#fff", fontWeight:700, cursor:"pointer"}}>
                {t.addExam}
              </button>
            </>
          )}
        </div>

        <div style={{overflowY:"auto", display:"flex", flexDirection:"column", gap:8}}>
          {examList.length === 0 && <div style={{fontSize:13, color:textMuted2, textAlign:"center", padding:"20px 0"}}>{t.noExamSubjects}</div>}
          {examList.map(([s, info]) => {
            const topicCount = Object.keys(info?.topics || {}).length;
            return (
              <div key={s} style={{display:"flex", alignItems:"center", justifyContent:"space-between", border:`1px solid ${cardBorder}`, borderRadius:12, padding:"10px 14px"}}>
                <div>
                  <div style={{fontSize:14, fontWeight:600}}>{s}</div>
                  <div style={{fontSize:11, color:textMuted2, fontWeight:600, marginTop:2}}><Num>{nf(topicCount)}</Num> {t.topicsLabel}</div>
                </div>
                <button onClick={()=>onRemove(s)} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2}}><Trash2 size={15}/></button>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function CalendarModal({ t, lang, nf, monthName, weekdayShort, calMonth, setCalMonth, entries, onClose, onSelectDay, cardBg, cardBorder, textMain, textMuted2, accent, dark, today }) {
  const y = calMonth.getFullYear(), m = calMonth.getMonth();
  const firstDay = new Date(y, m, 1);
  const startOffset = firstDay.getDay();
  const daysInMonth = new Date(y, m+1, 0).getDate();
  const cells = [];
  for (let i=0;i<startOffset;i++) cells.push(null);
  for (let d=1; d<=daysInMonth; d++) cells.push(new Date(y,m,d));

  const shortDays = lang==="bn" ? ["র","সো","ম","বু","বৃ","শু","শ"] : ["S","M","T","W","T","F","S"];

  return (
    <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,0.45)", display:"flex", alignItems:"center", justifyContent:"center", zIndex:50, padding:16}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:cardBg, width:"100%", maxWidth:420, borderRadius:22, padding:20, color:textMain}}>
        <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:6}}>
          <div style={{fontSize:15, fontWeight:800}}>{t.monthOverview}</div>
          <button onClick={onClose} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2}}><X size={20}/></button>
        </div>
        <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", margin:"10px 0 14px"}}>
          <button onClick={()=>setCalMonth(new Date(y,m-1,1))} style={{border:`1px solid ${cardBorder}`, background:"transparent", borderRadius:10, width:32,height:32, display:"flex",alignItems:"center",justifyContent:"center", cursor:"pointer", color:textMain}}><ChevronLeft size={16}/></button>
          <div style={{fontWeight:700, fontSize:15}}>{monthName(m)} <Num>{nf(y)}</Num></div>
          <button onClick={()=>setCalMonth(new Date(y,m+1,1))} style={{border:`1px solid ${cardBorder}`, background:"transparent", borderRadius:10, width:32,height:32, display:"flex",alignItems:"center",justifyContent:"center", cursor:"pointer", color:textMain}}><ChevronRight size={16}/></button>
        </div>
        <div style={{display:"grid", gridTemplateColumns:"repeat(7,1fr)", gap:4, marginBottom:6}}>
          {shortDays.map((d,i)=>(<div key={i} style={{textAlign:"center", fontSize:10, fontWeight:700, color:textMuted2}}>{d}</div>))}
        </div>
        <div style={{display:"grid", gridTemplateColumns:"repeat(7,1fr)", gap:4}}>
          {cells.map((d,i) => {
            if (!d) return <div key={i}/>;
            const dk = dateKey(d);
            const list = entries[dk] || [];
            const hasAny = list.length > 0;
            const doneAll = hasAny && list.every(x=>x.done);
            const isToday = dk === dateKey(today);
            const future = d > today;
            return (
              <button key={i} onClick={()=>onSelectDay(d)} disabled={future && !hasAny}
                style={{aspectRatio:"1", border: isToday ? `1.5px solid ${accent}` : "1px solid transparent", borderRadius:10, background: dark?"#1C1A17":"#F8F5EE", cursor:(future&&!hasAny)?"default":"pointer", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", gap:3, opacity: (future&&!hasAny)?0.4:1}}>
                <span style={{fontSize:12, fontWeight:600, color:textMain}}><Num>{nf(d.getDate())}</Num></span>
                <span style={{width:5,height:5,borderRadius:"50%", background: !hasAny ? "transparent" : (doneAll ? "#6E8B5E" : accent)}}/>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function DayDetailModal({ t, lang, nf, weekdayName, monthName, day, entries, allSubjects, onClose, cardBg, cardBorder, textMain, textMuted2, accent, dark }) {
  return (
    <div style={{position:"fixed", inset:0, background:"rgba(0,0,0,0.45)", display:"flex", alignItems:"flex-end", justifyContent:"center", zIndex:50}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:cardBg, width:"100%", maxWidth:480, borderRadius:"22px 22px 0 0", padding:"20px 20px 28px", color:textMain, maxHeight:"75vh", overflowY:"auto"}}>
        <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:4}}>
          <div>
            <div style={{fontSize:11, fontWeight:700, color:textMuted2}}>{weekdayName(day)}</div>
            <div style={{fontSize:19, fontWeight:800}}><Num>{nf(day.getDate())}</Num> {monthName(day.getMonth())}, <Num>{nf(day.getFullYear())}</Num></div>
          </div>
          <button onClick={onClose} style={{border:"none", background:"transparent", cursor:"pointer", color:textMuted2}}><X size={20}/></button>
        </div>
        <div style={{marginTop:16, display:"flex", flexDirection:"column", gap:8}}>
          {entries.length === 0 && <div style={{fontSize:13, color:textMuted2, textAlign:"center", padding:"20px 0"}}>{t.noData}</div>}
          {entries.map(e => {
            const c = colorForSubject(e.subject, allSubjects);
            return (
              <div key={e.id} style={{border:`1px solid ${cardBorder}`, borderRadius:14, padding:"11px 14px", display:"flex", alignItems:"center", gap:10}}>
                <div style={{width:8,height:8,borderRadius:"50%", background:c.bg, flexShrink:0}}/>
                <div style={{flex:1}}>
                  <div style={{fontSize:11, fontWeight:700, color:c.bg}}>{e.subject}</div>
                  <div style={{fontSize:14, fontWeight:600}}>{e.topic}</div>
                </div>
                <div style={{fontSize:11, fontWeight:700, color: e.done ? "#6E8B5E" : textMuted2, background: e.done ? "rgba(110,139,94,0.15)" : (dark?"#37332C":"#EFE9DC"), padding:"4px 9px", borderRadius:20}}>
                  {e.done ? t.done : t.notDone}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
